-- Formación pasa al formato «Carta»: una sola columna estrecha, como una
-- página de libro, con el texto de entrada, las cuatro propuestas con su nombre
-- en versalitas y el cierre (abierto a todos, la Agenda y los sacramentos en la
-- parroquia). Sin tarjetas ni preguntas: todo eso va ya en la carta.
--
-- Solo se sustituye la página que sigue con el texto de partida: si alguien ya
-- la ha editado en el CMS, se queda como está.

UPDATE `ContenidoPagina` SET `datos` = '{"cabecera":{"titulo":"Formación","subtitulo":"Crecer en la fe para entender lo que celebramos.","foto":"","fotoAlt":""},"bloques":[{"tipo":"texto","titulo":"","presentacion":{"estilo":"carta"},"html":"<p>La formación es uno de los pilares del Grupo Parroquial. No se trata de acumular conocimientos, sino de ayudar a cada hermano a conocer mejor a Dios, a vivir el Evangelio en lo de cada día y a entender lo que celebramos: por qué rezamos un triduo, qué significa el besamanos o por qué salimos a la calle.</p><h3>Catequesis y charlas</h3><p>Durante el curso, sesiones para profundizar en la fe, la liturgia y la devoción a la Virgen.</p><h3>Retiros y oración</h3><p>Momentos para parar, rezar juntos y prepararse para los tiempos fuertes del año: el Adviento y la Cuaresma.</p><h3>La espiritualidad de la Pasión</h3><p>De la mano de los Pasionistas, que nos acompañan en la parroquia, con la Cruz como escuela de amor.</p><h3>Jóvenes y nuevos hermanos</h3><p>Una atención especial para que conozcan la historia, los fines y las tradiciones del Grupo.</p><p>Todo lo que proponemos está abierto a hermanos, devotos y a cualquiera que quiera acercarse, y las fechas se anuncian en la Agenda. La preparación para los sacramentos la lleva la parroquia de Santa María Goretti: pregunta en el despacho parroquial, los martes y viernes de 18:00 a 20:00.</p>"},{"tipo":"cita","titulo":"","presentacion":{"estilo":"franja","alineacion":"centro"},"texto":"María conservaba todas estas cosas, meditándolas en su corazón.","autor":"","fuente":"Evangelio según san Lucas, 2, 19"},{"tipo":"botones","titulo":"","presentacion":{"alineacion":"centro"},"botones":[{"texto":"Ver la agenda","enlace":"/agenda","estilo":"principal"},{"texto":"Escríbenos","enlace":"/contacto","estilo":"secundario"}]}]}'
WHERE `slug` = 'formacion' AND `datos` LIKE '%"titulo":"Qué ofrecemos"%' AND `datos` LIKE '%Una atención especial para que conozcan la historia%';
